def calc(expr: str) -> int | str:
    def parse_int(s: str) -> int:
        if len(s) <= 4000:
            return int(s)
        val = 0
        for i in range(0, len(s), 4000):
            chunk = s[i : i + 4000]
            val = val * (10 ** len(chunk)) + int(chunk)
        return val

    tokens: list[int | str] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            j = i + 1
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            tokens.append(parse_int(expr[i:j]))
            i = j
        else:
            tokens.append(ch)
            i += 1

    pos = 0
    m = len(tokens)

    def parse_expr() -> int:
        nonlocal pos
        val = parse_mul()
        while pos < m and tokens[pos] in ("+", "-"):
            op = tokens[pos]
            pos += 1
            rhs = parse_mul()
            if op == "+":
                val += rhs
            else:
                val -= rhs
        return val

    def parse_mul() -> int:
        nonlocal pos
        val = parse_unary()
        while pos < m and tokens[pos] in ("*", "/", "%"):
            op = tokens[pos]
            pos += 1
            rhs = parse_unary()
            if op == "*":
                val *= rhs
            elif op == "/":
                if rhs == 0:
                    raise ArithmeticError
                q = abs(val) // abs(rhs)
                val = -q if (val < 0) ^ (rhs < 0) else q
            else:
                if rhs == 0:
                    raise ArithmeticError
                r = abs(val) % abs(rhs)
                val = -r if val < 0 else r
        return val

    def parse_unary() -> int:
        nonlocal pos
        chain: list[tuple[bool, int]] = []
        while True:
            neg = False
            while pos < m and tokens[pos] == "-":
                neg = not neg
                pos += 1
            val = parse_primary()
            chain.append((neg, val))
            if pos < m and tokens[pos] == "^":
                pos += 1
            else:
                break

        neg, acc = chain[-1]
        if neg:
            acc = -acc
        for idx in range(len(chain) - 2, -1, -1):
            neg, base = chain[idx]
            if acc < 0:
                raise ArithmeticError
            if acc == 0:
                acc = 1
            elif base == 0:
                acc = 0
            elif base == 1:
                acc = 1
            elif base == -1:
                acc = -1 if (acc & 1) else 1
            else:
                acc = base**acc
            if neg:
                acc = -acc
        return acc

    def parse_primary() -> int:
        nonlocal pos
        tok = tokens[pos]
        if isinstance(tok, int):
            pos += 1
            return tok
        pos += 1
        val = parse_expr()
        pos += 1
        return val

    try:
        return parse_expr()
    except ArithmeticError:
        return "error"
